using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
[InitializeOnLoad] public static class InputV3Checks {
 const string Running="InputNineVirtualPlayChecks";
 static InputV3Checks(){if(SessionState.GetBool(Running,false))EditorApplication.update+=PlayEntry;}
 static void PlayEntry(){if(!EditorApplication.isPlaying||Time.frameCount<2)return;SessionState.SetBool(Running,false);EditorApplication.update-=PlayEntry;Run();}

 static int count;static List<string> rows;static string report;static void Check(bool ok,string name){rows.Add((ok?"PASS ":"FAIL ")+name);if(!ok)throw new Exception(name);count++;}
 static TrainingCommand[] Step(CharacterCommandResolver e,long f,int down,int held,CharacterDirectionalMove[] d=null)=>e.Sample(f,down,held,CharacterAttackSlot.AwariDefaults(),d);
 static GamepadState Pad(int mask,bool modifier=false){var state=new GamepadState();GamepadButton[] buttons={GamepadButton.West,GamepadButton.North,GamepadButton.RightShoulder,GamepadButton.South,GamepadButton.East};for(int i=0;i<5;i++)if((mask&(1<<i))!=0)state=state.WithButton(buttons[i]);if((mask&32)!=0)state.rightTrigger=1;state.leftTrigger=modifier?1:0;return state;}
 public static void Run(){if(!EditorApplication.isPlaying){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Shioka/Scenes/CombatFormulaComparison.unity");SessionState.SetBool(Running,true);EditorApplication.update-=PlayEntry;EditorApplication.update+=PlayEntry;EditorApplication.EnterPlaymode();return;}rows=new List<string>();count=0;var args=Environment.GetCommandLineArgs();int ri=Array.IndexOf(args,"-inputV3Report");report=ri<0?"Temp/input-v3.txt":args[ri+1];try{Pure();Virtual();rows.Add(count+" PASS, 0 FAIL");File.WriteAllLines(report,rows);Debug.Log(rows.Last());EditorApplication.Exit(0);}catch(Exception e){rows.Add("EXCEPTION "+e);File.WriteAllLines(report,rows);Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Pure(){var e=new CharacterCommandResolver();for(int i=0;i<6;i++)Check(Step(e,100+i,1<<i,1<<i).Length==1,"single immediate slot "+i);Check(Step(e,200,5,5).SequenceEqual(new[]{TrainingCommand.Light,TrainingCommand.Heavy}),"LP+HP produces two singles, no Special");Check(!Step(e,201,40,40).Contains(TrainingCommand.Special2),"LK+HK no special dependency");Check(Step(e,202,448,448).Length==0,"additional J/K/L unassigned");Check(e.Sample(203,2,2,CharacterAttackSlot.AwariDefaults(),null,6).Single()==TrainingCommand.Medium,"undefined 6MP falls back to default MP");var defined=new[]{new CharacterDirectionalMove{slot=BattleAttackSlot.B,direction=6,defined=true,command=TrainingCommand.Heavy,displayName="test"}};Check(e.Sample(204,2,2,null,defined,6).Single()==TrainingCommand.Heavy,"defined contextual move selected without changing category");var technique=new TrainingMove{category=TechniqueCategory.Delirium};Check(technique.category==TechniqueCategory.Delirium,"Delirium is move metadata, not a button");var recorder=new TrainingRecorder();recorder.RecordKey();for(int i=0;i<180;i++)recorder.Tick(default);recorder.Tick(new TrainingInputFrame{AttackPressedMask=1,AttackHeldMask=1,ForceHeld=true,RecordPressed=true});recorder.RecordKey();Check(recorder.PlayKey(),"logical recording playable");var f=recorder.Tick(default);Check(f.ForceHeld&&f.AttackPressedMask==1&&!f.RecordPressed,"Mania and slot retained, recording hotkey excluded");Check(TrainingCommandHistory.Name(TrainingCommand.Light)=="LP","fallback label retained");var buffer=new TrainingCommandBuffer();buffer.Push(TrainingCommand.Light);for(int i=0;i<9;i++)buffer.Advance(1f/60);Check(buffer.Count==1&&buffer.Frame==9,"ordinary buffer retains command through frame9");buffer.Advance(1f/60);Check(buffer.Count==0&&buffer.Trace.Last().Outcome==TrainingCommandOutcome.Expired,"ordinary buffer expiry at frame10 unchanged");}
 static void Virtual(){var old=InputSystem.settings;var settings=UnityEngine.Object.Instantiate(old);Keyboard keyboard=null;Gamepad pad=null;TrainingDeviceInput source=null;TrainingMenuInput menu=null;TrainingInputConfig config=null;try{settings.updateMode=InputSettings.UpdateMode.ProcessEventsManually;settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=settings;keyboard=InputSystem.AddDevice<Keyboard>();pad=InputSystem.AddDevice<Gamepad>();config=UnityEngine.Object.Instantiate(Resources.Load<TrainingInputConfig>("TrainingInputConfig"));Check(config.layoutVersion==3,"live config v3");Check(config.ValidateV3(out var error),"default bindings valid: "+error);source=new TrainingDeviceInput(config,false);source.Map.Enable();int observed=0;source.Map["A"].performed+=ctx=>{observed++;rows.Add("OBS A "+ctx.ReadValue<float>()+" device="+ctx.control.device.displayName);};Action neutral=()=>{InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();source.Read(true);};Func<Key[],TrainingInputFrame> key=keys=>{InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));InputSystem.Update();return source.Read(true);};Func<GamepadState,bool,TrainingInputFrame> game=(state,training)=>{InputSystem.QueueStateEvent(pad,state);InputSystem.Update();return source.Read(training);};neutral();
 Key[] keys6={Key.J,Key.K,Key.L,Key.M,Key.Comma,Key.Period};for(int i=0;i<6;i++){neutral();var keyframe=key(new[]{keys6[i]});rows.Add("OBS key="+i+" mask="+keyframe.AttackPressedMask+" value="+keyboard.jKey.ReadValue()+" controls="+source.Map["A"].controls.Count+" enabled="+source.Map.enabled+" events="+observed);Check(keyframe.AttackPressedMask==(1<<i),"keyboard slot "+i);neutral();Check(game(Pad(1<<i),true).AttackPressedMask==(1<<i),"pad slot "+i);}
 neutral();var shortState=new KeyboardState(Key.J);InputSystem.QueueStateEvent(keyboard,shortState);InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();var tap=source.Read(true);Check(tap.AttackPressedMask==1&&tap.AttackHeldMask==0,"tick-between short tap not lost");neutral();var u=key(new[]{Key.U});Check(!u.ForceHeld&&!u.FdHeld&&u.AttackPressedMask==0,"U FD removed");neutral();Check(key(new[]{Key.J,Key.M}).AttackPressedMask==9,"old FD pair remains character slots only");neutral();var oldThrow=key(new[]{Key.K,Key.Comma});Check(!oldThrow.Commands.Contains(TrainingCommand.Throw),"old system throw pair removed");
 neutral();Check(key(new[]{Key.I}).Commands.Contains(TrainingCommand.Throw),"I Throw");neutral();Check(key(new[]{Key.Semicolon}).Commands.Contains(TrainingCommand.Cancel),"semicolon TRC");neutral();Check(game(new GamepadState().WithButton(GamepadButton.LeftShoulder),true).Commands.Contains(TrainingCommand.Cancel),"L1 TRC");foreach(var shift in new[]{Key.LeftShift,Key.RightShift}){neutral();Check(key(new[]{shift}).ForceHeld,"Force "+shift);}foreach(var ctrl in new[]{Key.LeftCtrl,Key.RightCtrl}){neutral();Check(key(new[]{ctrl}).Reset,"Reset "+ctrl);}neutral();Check(key(new[]{Key.R}).RecordPressed,"R Record");neutral();Check(key(new[]{Key.P}).PlayPressed,"P Play");neutral();var space=key(new[]{Key.Space});Check(space.DashPressed&&space.Dash,"Space dash edge");InputSystem.Update();Check(!source.Read(true).DashPressed,"dash no repeat pulse");
 for(int i=0;i<6;i++){neutral();var f=game(Pad(1<<i,true),true);Check(f.AttackPressedMask==0,"T1 consumes slot "+i);if(i==0)Check(f.RecordPressed,"T1 square record");if(i==1)Check(f.Commands.Contains(TrainingCommand.Throw),"T1 triangle throw");if(i==2)Check(f.ForceHeld,"T1 R1 force");if(i==3)Check(f.Reset,"T1 cross reset");if(i==4)Check(f.PlayPressed,"T1 circle play");if(i==5)Check(f.DashPressed,"T1 R2 dash");InputSystem.Update();f=source.Read(true);Check(!f.RecordPressed&&!f.PlayPressed&&!f.Reset&&!f.DashPressed&&f.Commands.Length==0,"held chord no repeated pulse "+i);}
 neutral();game(Pad(0,true),true);Check(game(Pad(4,true),true).ForceHeld,"modifier first");neutral();InputSystem.QueueStateEvent(pad,Pad(4));InputSystem.QueueStateEvent(pad,Pad(4,true));InputSystem.Update();Check(source.Read(true).ForceHeld,"modifier same tick, event order reversed");neutral();Check(game(Pad(4),true).AttackPressedMask==4,"face first emits slot");var late=game(Pad(4,true),true);Check(!late.ForceHeld&&late.AttackPressedMask==0,"modifier later no reinterpretation");neutral();game(Pad(4,true),true);var released=game(Pad(4,false),true);Check(!released.ForceHeld&&released.AttackPressedMask==0,"modifier released first no fallback");game(Pad(0),true);Check(game(Pad(4),true).AttackPressedMask==4,"repress ordinary");neutral();game(Pad(4,true),true);Check(!game(Pad(0,true),true).ForceHeld,"face released first");Check(game(Pad(4,true),true).ForceHeld,"repress chord");foreach(int mask in new[]{1,8,16}){neutral();var f=game(Pad(mask,true),false);Check(f.AttackPressedMask==0&&!f.Reset&&!f.RecordPressed&&!f.PlayPressed,"training chord inert outside mode "+mask);}
 neutral();source.Clear();Check(game(Pad(4,true),true).AttackPressedMask==0&&!source.Read(true).ForceHeld,"focus/menu boundary held input suppressed");neutral();Check(game(Pad(4,true),true).ForceHeld,"neutral then new press restores input");InputSystem.RemoveDevice(pad);pad=null;Check(!source.Read(true).ForceHeld,"device removal clears Force");pad=InputSystem.AddDevice<Gamepad>();neutral();config.modifier1Binding="<Gamepad>/rightShoulder";Check(!config.ValidateV3(out error),"modifier overlap rejected");config.modifier1Binding="<Gamepad>/leftTrigger";config.slotGamepadBindings[1]=config.slotGamepadBindings[0];Check(!config.ValidateV3(out error),"same context duplicate chord rejected");
 menu=new TrainingMenuInput();InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.East));InputSystem.Update();Check(menu.Read(1).confirm,"pad circle menu confirm");InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));InputSystem.Update();Check(menu.Read(2).cancel&&menu.Read(2).cancelFromPad,"pad cross menu cancel");InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.Start));InputSystem.Update();Check(menu.Read(3).option,"pad Options menu");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Escape));InputSystem.Update();Check(menu.Read(4).option,"Esc menu back");InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.K));InputSystem.Update();var textCancel=menu.Read(5);Check(textCancel.cancel&&!textCancel.cancelFromPad&&!textCancel.option,"typing K distinct from text-field back/cancel");source.Detach();source.Map.Dispose();config.slotGamepadBindings[1]="<Gamepad>/buttonNorth";config.modifier2Binding="<Gamepad>/rightStickPress";config.modifier2Actions[1]=ModifiedInputAction.Throw;source=new TrainingDeviceInput(config,false);source.Map.Enable();InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.QueueStateEvent(pad,new GamepadState());InputSystem.Update();source.Read(true);InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.RightStick).WithButton(GamepadButton.North));InputSystem.Update();var t2=source.Read(true);Check(t2.Commands.Contains(TrainingCommand.Throw)&&t2.AttackPressedMask==0,"optional T2 reusable ownership from data");
 }finally{menu?.Dispose();if(source!=null){source.Detach();source.Map.Dispose();}if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(pad!=null)InputSystem.RemoveDevice(pad);if(config!=null)UnityEngine.Object.DestroyImmediate(config);InputSystem.settings=old;UnityEngine.Object.DestroyImmediate(settings);}}
}
